mapper.select:
SELECT oa.id, oa.actor_user_id AS actorUserId, u.username AS actorUsername, u.display_name AS actorName, oa.actor_role AS actorRole, oa.actor_school_id AS actorSchoolId, actor_school.school_name AS actorSchoolName, oa.target_school_id AS targetSchoolId, oa.target_school_id AS schoolId, target_school.school_name AS targetSchoolName, target_school.school_name AS schoolName, oa.http_method AS httpMethod, oa.request_path AS requestPath, oa.response_status AS responseStatus, oa.source_fingerprint AS sourceFingerprint, oa.occurred_at AS occurredAt FROM operation_audit oa JOIN sys_user u ON u.id = oa.actor_user_id LEFT JOIN school actor_school ON actor_school.id = oa.actor_school_id LEFT JOIN school target_school ON target_school.id = oa.target_school_id
oa.target_school_id = #{schoolId}
AND oa.actor_user_id = #{actorUserId}
AND oa.http_method = #{httpMethod}
AND oa.request_path LIKE CONCAT(#{pathPrefix}, '%')
AND oa.occurred_at >= #{occurredFrom}
AND oa.occurred_at <= #{occurredTo}
ORDER BY oa.occurred_at DESC, oa.id DESC LIMIT 1000
